void *calloc(size_t nmemb, size_t size) /* <=== calloc */ 
{
	void *p;
	uint32_t exceptions = malloc_lock(&malloc_ctx);

	p = raw_calloc(0, 0, nmemb, size, &malloc_ctx);
	malloc_unlock(&malloc_ctx, exceptions);
	return p;
}

TEE_Result crypto_cipher_update(void *ctx, uint32_t algo, /* <=== crypto_cipher_update */ 
				TEE_OperationMode mode, bool last_block,
				const uint8_t *data, size_t len, uint8_t *dst);

static TEE_Result get_user_u64_as_size_t(size_t *dst, uint64_t *src) /* <=== get_user_u64_as_size_t */ 
{
	uint64_t d = 0;
	TEE_Result res = tee_svc_copy_from_user(&d, src, sizeof(d));

	/*
	 * On 32-bit systems a size_t can't hold a uint64_t so we need to
	 * check that the value isn't too large.
	 */
	if (!res && ADD_OVERFLOW(0, d, dst))
		return TEE_ERROR_OVERFLOW;

	return res;
}

TEE_Result tee_svc_copy_kaddr_to_uref(uint32_t *uref, void *kaddr) /* <=== tee_svc_copy_kaddr_to_uref */ 
{
	uint32_t ref = tee_svc_kaddr_to_uref(kaddr);

	return tee_svc_copy_to_user(uref, &ref, sizeof(ref));
}

typeDefs:
struct tee_cryp_state {
	TAILQ_ENTRY(tee_cryp_state) link;
	uint32_t algo;
	uint32_t mode;
	vaddr_t key1;
	vaddr_t key2;
	void *ctx;
	tee_cryp_ctx_finalize_func_t ctx_finalize;
	enum cryp_state state;
}

struct user_ta_ctx {
	uaddr_t entry_func;
	uaddr_t dump_entry_func;
#ifdef CFG_TA_FTRACE_SUPPORT
	uaddr_t ftrace_entry_func;
#endif
